feed:
  New apps on {{ site.name }}
  Open-source Flatpak apps, hunted from everywhere


  {{ base_url(request) }}/feed.xml
  {{ (apps[0].first_seen if apps else None)|isodate }}
{% for app in apps %}  
    {{ app.name }}

    {{ base_url(request) }}/apps/{{ app.app_id }}
    {{ app.first_seen|isodate }}
    {% if app.developer_name %}{{ app.developer_name }}{% endif %}
    {{ app.summary }}
    {{ app.summary }} — {{ RISK_TEXT.get(app.risk_level, app.risk_level) }}, {{ TRUST_TEXT.get(app.trust, app.trust) }}{% if app.license %}, {{ app.license }}{% endif %}.
    {% for c in app.categories or [] %}{% endfor %}

{% endfor %}
